// PMS → market-to-revenue: "Read the message"          (workflow: PMS send · WhatsApp)
// Mode: Run Once for All Items.
//
// The PMS decides WHAT and WHEN (D27-98). This workflow only marks the guest as a
// booked guest in the sales inbox, so a reply does not start the greeting bot
// (D27-104), and then - for action "send" - sends the WhatsApp template.
//
// ── THE OWNER'S SETTINGS: edit these four, nothing below them ───────────────
// This app's Firebase project (the same one the other workflows name).
const PROJECT = "live-inventory1";
// Each PMS hotel code → this app's hotel id (src/hotels.js). A hotel missing
// here is refused, loudly, rather than marked under the wrong hotel.
const HOTELS = {
  "5EL": { id: "five-elements-akkalkot", name: "5 Elements Akkalkot" },
  "AMR": { id: "amrapali-kolhapur", name: "Amrapali" },
  "GLM": { id: "grand-lucent-mathura", name: "Hotel Grand Lucent" },
};
// The language each template was approved in, in WhatsApp Manager.
const LANGUAGE = "en";
// The PMS's kind of message → the Meta template, and the fields for its {{1}},
// {{2}}, … in order (docs/go-live/whatsapp-templates.md). A kind missing here
// is refused with a sentence the desk sees.
const TEMPLATES = {
  "guest-link-code": { name: "guest_page_code", code: "data.code" },
  "arrival-reminder": {
    name: "stay_reminder",
    body: ["data.guestName", "data.hotelName", "data.checkInText", "data.reference", "data.link"],
  },
  "checkin-link": {
    name: "checkin_link",
    body: ["data.guestName", "data.hotelName", "data.checkInText", "data.reference", "data.link"],
  },
  "review": { name: "review_request", body: ["to.name", "hotel.name", "data.link"] },
};
// How long a sent message id is remembered, so a retry is not sent twice.
const KEEP_DAYS = 30;
// ─────────────────────────────────────────────────────────────────────────────

const m = $input.first().json.body ?? {};
const stop = (statusCode, answer) => [{ json: { stop: true, statusCode, answer } }];

// Every PMS message carries its own id, the same on every retry of one message.
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(m.messageId ?? "")) {
  return stop(400, { ok: false, error: "No message id." });
}
if (m.action !== "send" && m.action !== "mark") {
  return stop(400, { ok: false, error: "The action is send or mark." });
}

// ALREADY SENT: the PMS timed out waiting for the answer and tried again. The
// guest has it; say so, and send nothing.
const memory = $getWorkflowStaticData("global");
memory.sent = memory.sent ?? {};
const now = Date.now();
for (const [id, at] of Object.entries(memory.sent)) {
  if (now - at > KEEP_DAYS * 86400000) delete memory.sent[id];
}
if (m.action === "send" && memory.sent[m.messageId]) {
  return stop(200, { ok: true, duplicate: true });
}

// The guest's number as this app keys it: digits, a 10-digit Indian number with 91.
let digits = String(m.to?.phone ?? "").replace(/\D/g, "");
if (digits.length === 10) digits = `91${digits}`;
if (digits.length < 11) return stop(422, { ok: false, error: "No WhatsApp number for the guest." });

const numberId = String(m.from?.phoneNumberId ?? "").replace(/\D/g, "");
if (!numberId) return stop(422, { ok: false, error: "The PMS sent no WhatsApp number id." });

const hotel = HOTELS[m.hotel?.code];
if (!hotel) {
  return stop(422, { ok: false, error: `Hotel ${m.hotel?.code ?? "-"} is not in this workflow's HOTELS list.` });
}

// Meta refuses an EMPTY parameter, and a newline, a tab or four spaces inside one,
// with an error that names none of them.
const flat = (v) => String(v ?? "").replace(/[\n\t\r]+/g, " ").replace(/ {4,}/g, "   ").trim() || "-";
const pick = (path) => path.split(".").reduce((o, k) => (o == null ? o : o[k]), m);

let graphBody = null;
if (m.action === "send") {
  const t = TEMPLATES[m.kind];
  if (!t) return stop(422, { ok: false, error: `No WhatsApp template for "${m.kind}" in this workflow.` });
  const components = t.code
    // An Authentication template: the code in the body and in its copy button.
    ? [
        { type: "body", parameters: [{ type: "text", text: flat(pick(t.code)) }] },
        { type: "button", sub_type: "url", index: "0", parameters: [{ type: "text", text: flat(pick(t.code)) }] },
      ]
    : [{ type: "body", parameters: t.body.map((p) => ({ type: "text", text: flat(pick(p)) })) }];
  graphBody = {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: digits,
    type: "template",
    template: { name: t.name, language: { code: LANGUAGE }, components },
  };
}

const documents = `https://firestore.googleapis.com/v1/projects/${PROJECT}/databases/(default)/documents`;
return [{
  json: {
    stop: false,
    messageId: m.messageId,
    action: m.action,
    digits,
    numberId,
    hotel,
    guestName: flat(m.to?.name),
    reference: flat(m.data?.reference),
    documents,
    mappingUrl: `${documents}/numberMappings/${numberId}`,
    graphUrl: `https://graph.facebook.com/v23.0/${numberId}/messages`,
    graphBody,
  },
}];

// PMS → market-to-revenue: "Which lead"                (workflow: PMS send · WhatsApp)
// Mode: Run Once for All Items.
//
// Input: "Read the number" (HTTP Request, "Include Response Headers and Status"
// and "Never Error" on). The guest's lead is the one their REPLY will land on,
// so its id follows "Route to property" in the inbound workflow exactly:
//   a number shared by several hotels   <number id>__<digits>
//   a number mapped to one hotel        <that hotel>__<digits>
//   a number not mapped at all          UNASSIGNED__<digits>
// ⚠ Map the WhatsApp number in this app (Admin → WhatsApp routing) BEFORE the
//   first PMS message, or the guest is marked in Unassigned.

function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return { raw: body }; }
}

const msg = $("Read the message").first().json;
const res = $input.first().json;
const mapping = parse(res.body);

let owner;
if (res.statusCode === 200 && mapping.fields?.shared?.booleanValue) owner = msg.numberId;
else if (res.statusCode === 200 && mapping.fields?.hotelId?.stringValue) owner = mapping.fields.hotelId.stringValue;
else if (res.statusCode === 404) owner = "UNASSIGNED";
else {
  throw new Error(`Number mapping lookup for ${msg.numberId} failed: HTTP ${res.statusCode} `
    + JSON.stringify(mapping).slice(0, 300));
}

const conversationId = `${owner}__${msg.digits}`;
return [{ json: { ...msg, conversationId, leadUrl: `${msg.documents}/conversations/${conversationId}` } }];

// PMS → market-to-revenue: "Mark as booked"            (workflow: PMS send · WhatsApp)
// Mode: Run Once for All Items.
//
// Input: "Read the lead" (HTTP GET of the conversation, Never Error on).
// ONE write, always, so the commit that follows is never empty:
//   no lead yet     a lead made BOOKED - the shape the app's own "Add enquiry"
//                   writes, so the inbox shows it like any other
//   a lead          status BOOKED, the PMS booking's reference, booked now -
//                   what the app's own "Mark booked" writes (setStatus)
//   already BOOKED  only the reference, to the newest PMS booking
// A booked lead is not reopened by a reply (3-build-firestore-commit.js), so
// the guest's answer is a message on it: no greeting, no "Which hotel?".
// No money is written: the PMS sends none, and a zero would be a figure
// nobody set.

function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return { raw: body }; }
}

const msg = $("Which lead").first().json;
const res = $input.first().json;
const lead = parse(res.body);
const s = (v) => ({ stringValue: String(v) });
const name = `${msg.documents.replace("https://firestore.googleapis.com/v1/", "")}/conversations/${msg.conversationId}`;

let write;
if (res.statusCode === 404) {
  write = {
    update: {
      name,
      fields: {
        hotelId: s(msg.hotel.id),
        hotelName: s(msg.hotel.name),
        contactPhone: s(`+${msg.digits}`),
        contactDigits: s(msg.digits),
        contactName: s(msg.guestName),
        routingMethod: s("manual"),
        source: s("other"),
        attributionStatus: s("MANUAL"),
        status: s("BOOKED"),
        bookingRef: s(msg.reference),
        lastMessagePreview: s(`Booked in the PMS: ${msg.reference}`),
        lastMessageDirection: s("note"),
        unreadCount: { integerValue: "0" },
        propertyNumberId: s(msg.numberId),
      },
    },
    updateTransforms: ["receivedAt", "createdAt", "lastMessageAt", "bookedAt", "updatedAt"]
      .map((fieldPath) => ({ fieldPath, setToServerValue: "REQUEST_TIME" })),
    currentDocument: { exists: false },
  };
} else if (res.statusCode === 200) {
  const booked = lead.fields?.status?.stringValue === "BOOKED";
  write = {
    update: { name, fields: booked
      ? { bookingRef: s(msg.reference) }
      : { status: s("BOOKED"), bookingRef: s(msg.reference) } },
    updateMask: { fieldPaths: booked ? ["bookingRef"] : ["status", "bookingRef"] },
    updateTransforms: (booked ? ["updatedAt"] : ["bookedAt", "updatedAt"])
      .map((fieldPath) => ({ fieldPath, setToServerValue: "REQUEST_TIME" })),
    currentDocument: { exists: true },
  };
} else {
  throw new Error(`Reading lead ${msg.conversationId} failed: HTTP ${res.statusCode} `
    + JSON.stringify(lead).slice(0, 300));
}

return [{ json: { ...msg, commitBody: { writes: [write] } } }];

// PMS → market-to-revenue: "After the mark"            (workflow: PMS send · WhatsApp)
// Mode: Run Once for All Items.
//
// Input: "Write the mark" (the Firestore commit, Never Error on).
// FAILED_PRECONDITION means another PMS message made this lead a moment ago:
// the guest is marked either way. A mark that failed does NOT stop the message
// itself - the guest's code or reminder matters more than the inbox - and the
// PMS writes the reason down.

function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return { raw: body }; }
}

const msg = $("Mark as booked").first().json;
const res = $input.first().json;
const marked = res.statusCode === 200 || parse(res.body).error?.status === "FAILED_PRECONDITION";
const why = marked ? null : `The inbox was not marked (HTTP ${res.statusCode}).`;

if (msg.action === "mark") {
  return [{ json: marked
    ? { stop: true, statusCode: 200, answer: { ok: true, marked: true } }
    : { stop: true, statusCode: 502, answer: { ok: false, error: why } } }];
}
return [{ json: { ...msg, stop: false, markProblem: why } }];

// PMS → n8n: "Remember it"                                (both PMS send workflows)
// Mode: Run Once for All Items.
//
// Input: the send (HTTP Request with Never Error on, or the email node's
// success / error output). Sent: its id is remembered, so the PMS's retry of
// the SAME message is answered "already sent" and not sent again. Not sent:
// nothing is remembered - the PMS's next try must really try.

function parse(body) {
  if (typeof body !== "string") return body ?? {};
  try { return JSON.parse(body); } catch { return { raw: body }; }
}

const msg = $("After the mark").first().json;
const res = $input.first().json;
const sent = res.statusCode !== undefined
  ? res.statusCode >= 200 && res.statusCode < 300
  : !res.error;

if (!sent) {
  const said = res.statusCode !== undefined
    ? `WhatsApp refused it (HTTP ${res.statusCode}): ${parse(res.body).error?.message ?? ""}`
    : `The email did not go: ${res.error?.message ?? res.error ?? ""}`;
  return [{ json: { statusCode: 502, answer: { ok: false, error: said.slice(0, 300).trim() } } }];
}

$getWorkflowStaticData("global").sent ??= {};
$getWorkflowStaticData("global").sent[msg.messageId] = Date.now();
return [{ json: { statusCode: 200, answer: { ok: true, ...(msg.markProblem ? { note: msg.markProblem } : {}) } } }];
